from http.server import BaseHTTPRequestHandler, HTTPServer
import json

USERS = {"alice": {"role": "user"}, "admin": {"role": "admin"}}
ORDERS = {"1001": {"owner": "alice", "amount": 120}, "1002": {"owner": "admin", "amount": 90}}

class Handler(BaseHTTPRequestHandler):
    def _json(self, status, value):
        body = json.dumps(value).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        prefix = "/api/orders/"
        if not self.path.startswith(prefix):
            return self._json(404, {"error": "not found"})
        order_id = self.path[len(prefix):]
        username = self.headers.get("X-Lab-User", "alice")
        user, order = USERS.get(username), ORDERS.get(order_id)
        if user is None or order is None:
            return self._json(404, {"error": "not found"})
        if username != order["owner"] and user["role"] != "admin":
            return self._json(404, {"error": "not found"})
        return self._json(200, {"id": order_id, "amount": order["amount"]})

    def do_POST(self):
        if self.path != "/api/report":
            return self._json(404, {"error": "not found"})
        length = int(self.headers.get("Content-Length", "0"))
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            return self._json(400, {"error": "invalid json"})
        if not isinstance(payload, dict) or not {"event", "severity"}.issubset(payload):
            return self._json(400, {"error": "invalid request"})
        if payload["severity"] not in {"low", "medium", "high", "critical"}:
            return self._json(400, {"error": "invalid severity"})
        return self._json(202, {"accepted": True})

    def log_message(self, format, *args):
        return

if __name__ == "__main__":
    HTTPServer(("127.0.0.1", 8000), Handler).serve_forever()
